{
  "name": "Luminos多轴精密定位台",
  "name_en": "Luminos Multi-Axis Precision Positioning Stage",
  "manufacturer": "Zaber Technologies",
  "description": "Luminos多轴精密定位台是一种电动位移与角度调节平台，可提供线性轴和旋转轴运动，用于在实验室中对光学元件、光纤、样品或探头进行高精度定位、对准和扫描。此类设备常用于光学耦合、器件装调和精密运动控制实验。",
  "description_en": "The Luminos multi-axis precision positioning stage is a motorized positioning platform that provides linear and rotational motion for high-precision placement, alignment, and scanning of optical components, fibers, samples, or probes in the laboratory. It is commonly used for optical coupling, component alignment, and precision motion-control experiments.",
  "tag_hints": [
    "optical alignment",
    "multi-axis positioning",
    "motorized translation stage",
    "motorized rotation stage",
    "fiber alignment",
    "XYZ pitch yaw roll",
    "microstepping",
    "backlash compensation"
  ],
  "actions": [
